
import { reactive, toRefs, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Edit, Delete } from '@element-plus/icons-vue'
import { orderList } from '@ADMIN/const/data'
export default {
  name: 'baseTable',
  setup() {
    const query = reactive({
      address: '',
      name: '',
      pageIndex: 1,
      pageSize: 10,
    })
    const from = reactive({
      address: '',
      name: '',
      phone: '',
      idx: '',
    })
    const pageTotal = ref(4)
    const tableData = ref(orderList)

    // 查询
    const handleSearch = () => {
      query.pageIndex = 1
    }
    // 分页导航
    const handlePageChange = (index: number) => {
      query.pageIndex = index
    }

    // 表格编辑时弹窗和保存
    const editVisible = ref(false)
    const handleEdit = (idx: string, val: any) => {
      from.address = val.address
      from.name = val.name
      from.phone = val.phone
      from.idx = idx
      editVisible.value = true
    }

    //编辑框确认
    const saveEdit = (idx: number) => {
      tableData.value[idx].address = from.address
      tableData.value[idx].name = from.name
      tableData.value[idx].phone = from.phone
      editVisible.value = false
    }

    // 删除
    const handleDelete = (index: number) => {
      ElMessageBox.confirm('确定要删除吗？', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning',
      })
        .then(() => {
          tableData.value = tableData.value.filter((item, idx) => idx != index)
          ElMessage.success('删除成功')
        })
        .catch(() => {
          ElMessage({
            type: 'info',
            message: '已取消删除！',
          })
        })
    }

    return {
      ...toRefs(query),
      handleSearch,
      tableData,
      handlePageChange,
      handleEdit,
      pageTotal,
      editVisible,
      saveEdit,
      handleDelete,
      Delete,
      Edit,
      from,
    }
  },
}
